var ENZ = {
  EcoRI:   { site: 'GAATTC',    cut: 1 },   // G^AATTC
  BamHI:   { site: 'GGATCC',    cut: 1 },   // G^GATCC
  HindIII: { site: 'AAGCTT',    cut: 1 },   // A^AGCTT
  EcoRV:   { site: 'GATATC',    cut: 3 },   // GAT^ATC
  NotI:    { site: 'GCGGCCGC',  cut: 2 },   // GC^GGCCGC
  XhoI:    { site: 'CTCGAG',    cut: 1 }    // C^TCGAG
};
function listEnzymes(){ return Object.keys(ENZ); }
function normSeq(s){ return String(s).toUpperCase().replace(/U/g,'T').replace(/[^ACGT]/g,''); }
// 在序列中查找酶切位点，返回切割坐标（位点内 cut 偏移处）与片段
function cut(seq, name){
  var e = ENZ[name]; if(!e) return {error:'unknown enzyme'};
  var s = normSeq(seq); var site = e.site; var positions = [];
  var idx = s.indexOf(site);
  while(idx !== -1){ positions.push(idx + e.cut); idx = s.indexOf(site, idx + 1); }
  var fragments = []; var start = 0;
  for(var i=0;i<positions.length;i++){ fragments.push(s.slice(start, positions[i])); start = positions[i]; }
  fragments.push(s.slice(start));
  return { enzyme:name, site:site, positions:positions, fragments:fragments, count:fragments.length };
}
var EXPORTS={ ENZ:ENZ, listEnzymes:listEnzymes, normSeq:normSeq, cut:cut };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.RestrictionEnzymeForgePure = EXPORTS; }
